"""Shared fixtures. Everything here is SAMPLE DATA generated by the simulator."""

from __future__ import annotations

import json

import pytest
from shapely.geometry import Polygon

import simulate_telemetry as sim
import spray_planner


def ndjson_rows(samples, flow_meter=False, t0=1_778_736_600.0):
    """The rows the gateway would emit for these simulator samples."""
    rows = []
    for s in samples:
        ts = round(t0 + s["t"], 3)
        boot_ms = int(s["t"] * 1000)
        rows.append({"ts": ts, "type": "VFR_HUD", "groundspeed_ms": s["groundspeed_ms"],
                     "heading_deg": int(s["heading_deg"]), "alt_msl_m": s["alt_rel_m"],
                     "climb_ms": 0.0, "throttle_pct": 55})
        servos = [1500] * 16
        servos[8] = s["pump_pwm"]
        rows.append({"ts": ts, "type": "SERVO_OUTPUT_RAW", "servo_raw": servos})
        if flow_meter:
            rows.append({"ts": ts, "type": "NAMED_VALUE_FLOAT", "name": "FLOW",
                         "value": s["flow_lpm"]})
        rows.append({"ts": ts, "type": "GLOBAL_POSITION_INT",
                     "lat": round(s["lat"], 7), "lon": round(s["lon"], 7),
                     "alt_rel_m": s["alt_rel_m"], "time_boot_ms": boot_ms})
        if boot_ms % 1000 == 0:
            rows.append({"ts": ts, "type": "SYS_STATUS",
                         "battery_voltage_v": s["battery_v"], "battery_state": "OK"})
    return rows


def write_ndjson(path, samples, flow_meter=False):
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        for row in ndjson_rows(samples, flow_meter):
            fh.write(json.dumps(row) + "\n")
    return path


