@pytest.fixture(scope="session")
def demo_boundary():
    return Polygon(spray_planner.field_boundary_lonlat(sim.DEMO_AREA_HA, sim.DEMO_WIDTH_M))


@pytest.fixture
def perfect_ndjson(tmp_path, perfect_samples):
    return write_ndjson(tmp_path / "perfect.ndjson", perfect_samples)


@pytest.fixture
def faulty_ndjson(tmp_path, faulty_samples):
    return write_ndjson(tmp_path / "faulty.ndjson", faulty_samples)


